import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, interpolate, spring } from '../remotionShim';
// --- Schema Definition ---


export type ProcessFlowProps = Record<string, any>;

// --- Sub-components ---

const ChevronArrow: React.FC<{
  color: string;
  delay: number;
  frame: number;
  fps: number;
  size: number;
}> = ({ color, delay, frame, fps, size }) => {
  // Arrow animation: Slide down + Fade in
  const opacity = interpolate(
    frame - delay,
    [0, 10],
    [0, 1],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );
  
  const translateY = interpolate(
    frame - delay,
    [0, 15],
    [-15, 0],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp", easing: (t) => t * (2 - t) }
  );

  // Continuous bobbing animation after entrance
  const bobbing = Math.sin((frame - delay) / 10) * (size * 0.1); // Scale bobbing with size
  const activeBobbing = interpolate(frame - delay, [20, 30], [0, 1], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });

  const strokeWidth = Math.max(4, size * 0.1); // Scale stroke with size

  return (
    <div
      style={{
        width: size * 1.5,
        height: size,
        display: "flex",
        justifyContent: "center",
        alignItems: "center",
        opacity,
        transform: `translateY(${translateY + (bobbing * activeBobbing)}px)`,
        margin: `${size * 0.2}px 0`,
      }}
    >
      <svg width={size} height={size} viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg">
        <path
          d="M7 10L12 15L17 10"
          stroke={color}
          strokeWidth={strokeWidth}
          strokeLinecap="round"
          strokeLinejoin="round"
          style={{ filter: `drop-shadow(0 0 ${size * 0.15}px ${color})` }}
        />
        <path
          d="M7 4L12 9L17 4" 
          stroke={color}
          strokeWidth={strokeWidth}
          strokeLinecap="round"
          strokeLinejoin="round"
          opacity="0" 
        />
      </svg>
    </div>
  );
};

const StepBox: React.FC<{
  text: string;
  color: string;
  textColor: string;
  accentColor: string;
  delay: number;
  frame: number;
  fps: number;
  width: number;
  height: number;
  fontSize: number;
}> = ({ text, color, textColor, accentColor, delay, frame, fps, width, height, fontSize }) => {
  
  // Spring entrance
  const scale = spring({
    frame: frame - delay,
    fps,
    config: { damping: 12, stiffness: 100, mass: 0.8 },
  });

  const opacity = interpolate(
    frame - delay,
    [0, 5],
    [0, 1],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );

  // Glow pulse effect
  const pulse = (Math.sin(frame / 15) + 1) / 2; // 0 to 1
  const glowOpacity = interpolate(pulse, [0, 1], [0.3, 0.6]);

  return (
    <div
      style={{
        opacity,
        transform: `scale(${scale})`,
        width: width,
        height: height,
        backgroundColor: color,
        borderRadius: Math.min(width, height) * 0.15, // Dynamic radius
        display: "flex",
        justifyContent: "center",
        alignItems: "center",
        position: "relative",
        boxShadow: `0 0 30px ${color}80, inset 0 0 30px ${accentColor}40`,
        border: `3px solid ${accentColor}60`,
      }}
    >
      {/* Inner glow pulse overlay */}
      <div
        style={{
          position: "absolute",
          top: 0,
          left: 0,
          right: 0,
          bottom: 0,
          borderRadius: Math.min(width, height) * 0.12,
          boxShadow: `inset 0 0 40px ${accentColor}`,
          opacity: glowOpacity,
          pointerEvents: "none",
        }}
      />
      
      <h1
        style={{
          color: textColor,
          fontFamily: "Arial, Helvetica, sans-serif",
          fontSize: fontSize,
          fontWeight: 900,
          margin: 0,
          textTransform: "uppercase",
          letterSpacing: "2px",
          textShadow: `0 0 15px ${color}, 0 0 25px white`,
          zIndex: 1,
          textAlign: "center",
          lineHeight: 1,
          width: "100%",
        }}
      >
        {text}
      </h1>
    </div>
  );
};

// --- Main Component ---

const ProcessFlow: React.FC<ProcessFlowProps> = ({
  primaryColor = "#6a0dad", // Deep purple
  accentColor = "#9d4edd", // Lighter purple
  textColor = "#ffffff",
  arrowColor = "#ffff00", // Bright yellow
  backgroundColor = "transparent", // Fixed: Default to transparent
  transparentBackground = false, // Added default value
  step1Text = "Strategy",
  step2Text = "Marketing",
  step3Text = "Sales",
  step4Text = "Product Delivery",
  // New Larger Defaults
  boxWidth = 850,
  boxHeight = 140,
  fontSize = 70,
  arrowSize = 40, // Fixed: Default size adjusted
  durationInSeconds = 10,
}) => {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();

  // Timing configuration
  const startDelay = 5;
  const stepDelay = 15; // Frames between steps

  return (
    <AbsoluteFill
      style={{
        backgroundColor: transparentBackground ? "transparent" : backgroundColor,
        display: "flex",
        flexDirection: "column",
        alignItems: "center",
        justifyContent: "center",
        padding: "40px",
      }}
    >
      {/* Step 1 */}
      <StepBox
        text={step1Text}
        color={primaryColor}
        accentColor={accentColor}
        textColor={textColor}
        delay={startDelay}
        frame={frame}
        fps={fps}
        width={boxWidth}
        height={boxHeight}
        fontSize={fontSize}
      />

      {/* Arrow 1 */}
      <ChevronArrow
        color={arrowColor}
        delay={startDelay + stepDelay * 0.5}
        frame={frame}
        fps={fps}
        size={arrowSize}
      />

      {/* Step 2 */}
      <StepBox
        text={step2Text}
        color={primaryColor}
        accentColor={accentColor}
        textColor={textColor}
        delay={startDelay + stepDelay}
        frame={frame}
        fps={fps}
        width={boxWidth}
        height={boxHeight}
        fontSize={fontSize}
      />

      {/* Arrow 2 */}
      <ChevronArrow
        color={arrowColor}
        delay={startDelay + stepDelay * 1.5}
        frame={frame}
        fps={fps}
        size={arrowSize}
      />

      {/* Step 3 */}
      <StepBox
        text={step3Text}
        color={primaryColor}
        accentColor={accentColor}
        textColor={textColor}
        delay={startDelay + stepDelay * 2}
        frame={frame}
        fps={fps}
        width={boxWidth}
        height={boxHeight}
        fontSize={fontSize}
      />

      {/* Arrow 3 */}
      <ChevronArrow
        color={arrowColor}
        delay={startDelay + stepDelay * 2.5}
        frame={frame}
        fps={fps}
        size={arrowSize}
      />

      {/* Step 4 */}
      <StepBox
        text={step4Text}
        color={primaryColor}
        accentColor={accentColor}
        textColor={textColor}
        delay={startDelay + stepDelay * 3}
        frame={frame}
        fps={fps}
        width={boxWidth}
        height={boxHeight}
        fontSize={fontSize}
      />
    </AbsoluteFill>
  );
};

